"""Private graph-copy experiments that avoid redundant corner-search work.

All seed searches, source certification, iteration limits and final corner
guards remain unchanged. A repeated parameter state is reused only after one
complete step has established it. Optional seed filtering keeps the original
crossing predicate, then interpolates parameters only for surviving pairs.
No production default is changed here.
"""
import hashlib

from . import curved_corner_nodes as corners
from .curved_quad_fair_nodes import assign_group


def copy_graph(original, *, stop_on_fixed_point=True, filter_seed_pairs=False):
    memo={};proof=[]
    def clone(tree):
        if tree.as_pointer() in memo:return memo[tree.as_pointer()]
        if tree.name.startswith(corners.PREFIX+'fixed-radius candidates v2'):
            fixed = stop_on_fixed_point or 'Exact fixed-point reuse v1' in tree.name
            filtered = filter_seed_pairs or 'Filter before seed interpolation v1' in tree.name
            if (fixed == ('Exact fixed-point reuse v1' in tree.name)
                    and filtered == ('Filter before seed interpolation v1' in tree.name)):result=tree
            else:
                result=corners.build(prepared_paths='Prepared paths v2' in tree.name,
                    polyline='Exact or smooth curb contacts v1' in tree.name,
                    stop_on_fixed_point=fixed,filter_seed_pairs=filtered)
                proof.append(dict(original=tree.name,candidate=result.name))
        else:
            changes=[(n.name,clone(n.node_tree)) for n in tree.nodes if n.type=='GROUP' and n.node_tree]
            changes=[(name,child) for name,child in changes if child!=tree.nodes[name].node_tree]
            result=tree.copy() if changes else tree
            if changes:
                result.name='Corner fixed-point dependency / '+hashlib.sha256(tree.name.encode()).hexdigest()[:16]
                for name,child in changes:assign_group(result.nodes[name],child)
        memo[tree.as_pointer()]=result
        return result
    result=clone(original)
    if not proof:raise ValueError('No original fixed-radius corner solvers in this graph')
    return result,proof
